export class SocialHomeComponent {
  menuOpen=signal(false);
  publicProfile=signal<PublicProfile|null>(null);
  private http=inject(HttpClient);private router=inject(Router);
  ready=signal(false);loading=signal(false);loadingMore=signal(false);busy=signal(false);profileOpen=signal(false);profileSaving=signal(false);profileName=signal('Membre de la communauté');posts=signal<SocialPost[]>([]);comments=signal<SocialComment[]>([]);notices=signal<Array<{id:string;message:string;createdAt:string}>>([]);blockedMembers=signal<BlockedMember[]>([]);notificationsOpen=signal(false);blocksOpen=signal(false);searchOpen=signal(false);editingPostId=signal('');nextCursor=signal<string|null>(null);openPost=signal('');userId=signal('');memberRole=signal('');error=signal('');status=signal('');notificationsEnabled=signal(true);savedMode=signal(false);mediaEnabled=signal(false);selectedMedia=signal<File[]>([]);mediaUrls=signal<Record<string,string>>({});reportingTarget=signal<{targetType:'POST'|'COMMENT'|'PROFILE';targetId:string}|null>(null);reportReason='SPAM';body='';commentBody='';searchTerm='';profileBio='';visibility:'TOUS_LES_FIDELES'|'MOI_SEUL'='TOUS_LES_FIDELES';pollEnabled=signal(false);pollOptions=['',''];pollClosesAt='';eventEnabled=signal(false);eventTitle='';eventStartsAt='';eventEndsAt='';eventLocation='';private replyParent='';
  groupsOpen=signal(false);groupsLoading=signal(false);groupsBusy=signal(false);groupsError=signal('');groups=signal<SocialGroup[]>([]);groupName='';groupDescription='';groupVisibility:'PUBLIC'|'PRIVATE'='PUBLIC';activeGroupId=signal('');activeGroupName=signal('');groupDiscussionLoading=signal(false);groupDiscussionError=signal('');groupPosts=signal<GroupPost[]>([]);groupPostBusy=signal(false);groupPostDraft='';openGroupPostId=signal('');groupComments=signal<GroupComment[]>([]);groupCommentDraft='';
  accountOpen=signal(false);accountBusy=signal(false);sessions=signal<AccountSession[]>([]);profileDiscoverable=signal(true);currentPassword='';newPassword='';confirmPassword='';deletionReason='';
  constructor(){this.http.get<{user:{id:string;role:string}}>(environment.apiUrl+'/auth/session').subscribe({next:result=>{if(['FIDELE','SECRETAIRE_PRESENCE','RESPONSABLE_SEMAINE'].includes(result.user.role)){this.userId.set(result.user.id);this.memberRole.set(result.user.role);this.ready.set(true);void this.loadFeed();void this.loadSettings();void this.loadMediaConfig();}else this.finish();},error:()=>this.finish()});}
  hasAttendanceAccess(){return ['SECRETAIRE_PRESENCE','RESPONSABLE_SEMAINE'].includes(this.memberRole());}
  roleLabel(){return this.memberRole()==='SECRETAIRE_PRESENCE'?'Secrétaire de présence':this.memberRole()==='RESPONSABLE_SEMAINE'?"Président d’un jour":'Membre fidèle';}
  initial(value:string){return value.slice(0,1).toLocaleUpperCase('fr-FR');}
  linkPreview(body:string){const match=body.match(/https?:\/\/[^\s<>"']{1,2048}/i);if(!match)return null;try{const url=new URL(match[0]);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)return null;return url.href;}catch{return null;}}
  linkHost(value:string){try{return new URL(value).hostname;}catch{return 'Lien externe';}}
  formatDate(value:string){return new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}
  async viewMemberProfile(id:string){this.error.set('');try{this.publicProfile.set(await firstValueFrom(this.http.get<PublicProfile>(environment.apiUrl+'/social/profiles/'+encodeURIComponent(id))));window.scrollTo({top:0,behavior:'smooth'});}catch(error:any){this.error.set(error?.error?.message??'Ce profil n’est pas accessible.');}}
  async loadFeed(cursor?:string){this.error.set('');if(cursor)this.loadingMore.set(true);else this.loading.set(true);try{const url=new URL(environment.apiUrl+(this.savedMode()?'/social/saved':'/social/posts'),location.origin);if(cursor)url.searchParams.set('cursor',cursor);url.searchParams.set('take','20');if(this.searchTerm.trim())url.searchParams.set('q',this.searchTerm.trim());const result=await firstValueFrom(this.http.get<{items:SocialPost[];nextCursor:string|null}>(url.toString()));this.posts.update(items=>cursor?[...items,...result.items]:result.items);this.nextCursor.set(result.nextCursor);for(const post of result.items)for(const image of post.media??[])void this.loadMedia(image.id);}catch(error:any){this.error.set(error?.error?.message??'Les actualités ne sont pas accessibles pour le moment.');}finally{this.loading.set(false);this.loadingMore.set(false);}}
  async loadMediaConfig(){try{const config=await firstValueFrom(this.http.get<{enabled:boolean}>(environment.apiUrl+'/social/media/config'));this.mediaEnabled.set(config.enabled);}catch{this.mediaEnabled.set(false);}}
  async loadMedia(id:string){if(this.mediaUrls()[id])return;try{const blob=await firstValueFrom(this.http.get(`${environment.apiUrl}/social/media/${id}`,{responseType:'blob'}));this.mediaUrls.update(urls=>({...urls,[id]:URL.createObjectURL(blob)}));}catch{}}
  selectMedia(event:Event){const files=Array.from((event.target as HTMLInputElement).files??[]);if(files.length>4){this.error.set('Vous pouvez joindre au maximum quatre fichiers.');this.selectedMedia.set(files.slice(0,4));return;}this.error.set('');this.selectedMedia.set(files);}
  clearMedia(){this.selectedMedia.set([]);const input=document.getElementById('post-media') as HTMLInputElement|null;if(input)input.value='';}
  clearSearch(){this.searchTerm='';this.searchOpen.set(false);this.nextCursor.set(null);void this.loadFeed();}
  openReport(targetType:'POST'|'COMMENT'|'PROFILE',targetId:string){this.reportReason='SPAM';this.reportingTarget.set({targetType,targetId});this.error.set('');}
  cancelReport(){this.reportingTarget.set(null);}
  async sendReport(){const target=this.reportingTarget();if(!target||this.busy())return;this.busy.set(true);try{await firstValueFrom(this.http.post(environment.apiUrl+'/social/reports',{...target,reason:this.reportReason}));this.status.set('Votre signalement a été transmis à l’équipe de modération.');this.reportingTarget.set(null);}catch(error:any){this.error.set(error?.error?.message??'Le signalement n’a pas pu être envoyé.');}finally{this.busy.set(false);}}
  toggleSearch(){this.searchOpen.update(open=>!open);this.menuOpen.set(false);if(this.searchOpen())setTimeout(()=>document.getElementById('community-search')?.focus(),0);}
  focusComposer(){this.menuOpen.set(false);document.getElementById('post-body')?.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>document.getElementById('post-body')?.focus(),350);}
  toggleMenu(){this.menuOpen.update(open=>!open);}
  async toggleGroups(){this.groupsOpen.update(open=>!open);this.profileOpen.set(false);this.accountOpen.set(false);this.notificationsOpen.set(false);this.blocksOpen.set(false);this.menuOpen.set(false);if(this.groupsOpen())await this.loadGroups();}
  async loadGroups(){this.groupsLoading.set(true);this.groupsError.set('');try{this.groups.set(await firstValueFrom(this.http.get<SocialGroup[]>(environment.apiUrl+'/social/groups')));}catch(error:any){this.groupsError.set(error?.error?.message??'Les groupes ne sont pas accessibles.');}finally{this.groupsLoading.set(false);}}
  async openGroupDiscussion(group:SocialGroup){this.activeGroupId.set(group.id);this.activeGroupName.set(group.name);this.groupDiscussionLoading.set(true);this.groupDiscussionError.set('');this.groupPosts.set([]);this.openGroupPostId.set('');try{this.groupPosts.set(await firstValueFrom(this.http.get<GroupPost[]>(`${environment.apiUrl}/social/groups/${group.id}/posts`)));}catch(error:any){this.groupDiscussionError.set(error?.error?.message??'Les échanges de ce groupe ne sont pas accessibles.');}finally{this.groupDiscussionLoading.set(false);}}
  closeGroupDiscussion(){this.activeGroupId.set('');this.groupPosts.set([]);this.groupComments.set([]);this.openGroupPostId.set('');}
  async publishGroupPost(){const groupId=this.activeGroupId(),body=this.groupPostDraft.trim();if(!groupId||!body||this.groupPostBusy())return;this.groupPostBusy.set(true);this.groupDiscussionError.set('');try{const post=await firstValueFrom(this.http.post<GroupPost>(`${environment.apiUrl}/social/groups/${groupId}/posts`,{body},{headers:new HttpHeaders({'Idempotency-Key':crypto.randomUUID()})}));this.groupPosts.update(posts=>[post,...posts]);this.groupPostDraft='';this.status.set('Votre message a été publié dans le groupe.');}catch(error:any){this.groupDiscussionError.set(error?.error?.message??'Le message n’a pas pu être publié.');}finally{this.groupPostBusy.set(false);}}
  async toggleGroupComments(post:GroupPost){if(this.openGroupPostId()===post.id){this.openGroupPostId.set('');return;}this.openGroupPostId.set(post.id);this.groupCommentDraft='';try{this.groupComments.set(await firstValueFrom(this.http.get<GroupComment[]>(`${environment.apiUrl}/social/groups/posts/${post.id}/comments`)));}catch(error:any){this.groupDiscussionError.set(error?.error?.message??'Les commentaires de cet échange ne sont pas accessibles.');}}
  async addGroupComment(post:GroupPost){const body=this.groupCommentDraft.trim();if(!body||this.groupPostBusy())return;this.groupPostBusy.set(true);try{const comment=await firstValueFrom(this.http.post<GroupComment>(`${environment.apiUrl}/social/groups/posts/${post.id}/comments`,{body}));this.groupComments.update(comments=>[...comments,comment]);this.groupPosts.update(posts=>posts.map(item=>item.id===post.id?{...item,commentCount:item.commentCount+1}:item));this.groupCommentDraft='';}catch(error:any){this.groupDiscussionError.set(error?.error?.message??'Le commentaire n’a pas pu être ajouté.');}finally{this.groupPostBusy.set(false);}}
  async deleteGroupPost(post:GroupPost){if(!confirm('Supprimer cet échange ?'))return;try{await firstValueFrom(this.http.delete(`${environment.apiUrl}/social/groups/posts/${post.id}`));this.groupPosts.update(posts=>posts.filter(item=>item.id!==post.id));this.status.set('L’échange a été supprimé.');}catch(error:any){this.groupDiscussionError.set(error?.error?.message??'L’échange n’a pas pu être supprimé.');}}
  async createGroup(){if(this.groupsBusy()||this.groupName.trim().length<3||this.groupDescription.trim().length<3)return;this.groupsBusy.set(true);this.groupsError.set('');try{await firstValueFrom(this.http.post(environment.apiUrl+'/social/groups',{name:this.groupName.trim(),description:this.groupDescription.trim(),visibility:this.groupVisibility}));this.groupName='';this.groupDescription='';this.groupVisibility='PUBLIC';this.status.set('Le groupe paroissial a été créé.');await this.loadGroups();}catch(error:any){this.groupsError.set(error?.error?.message??'Le groupe n’a pas pu être créé.');}finally{this.groupsBusy.set(false);}}
  async joinGroup(group:SocialGroup){this.groupsBusy.set(true);this.groupsError.set('');try{const result=await firstValueFrom(this.http.post<{message:string}>(`${environment.apiUrl}/social/groups/${group.id}/join`,{}));this.status.set(result.message);await this.loadGroups();}catch(error:any){this.groupsError.set(error?.error?.message??'La demande n’a pas pu être transmise.');}finally{this.groupsBusy.set(false);}}
  async leaveGroup(group:SocialGroup){this.groupsBusy.set(true);this.groupsError.set('');try{await firstValueFrom(this.http.delete(`${environment.apiUrl}/social/groups/${group.id}/membership`));this.status.set(`Vous avez quitté « ${group.name} ».`);await this.loadGroups();}catch(error:any){this.groupsError.set(error?.error?.message??'Vous ne pouvez pas quitter ce groupe.');}finally{this.groupsBusy.set(false);}}
  async acceptGroupRequest(group:SocialGroup,request:{id:string;displayName:string}){this.groupsBusy.set(true);this.groupsError.set('');try{await firstValueFrom(this.http.post(`${environment.apiUrl}/social/groups/${group.id}/requests/${request.id}/accept`,{}));this.status.set(`La demande de ${request.displayName} a été acceptée.`);await this.loadGroups();}catch(error:any){this.groupsError.set(error?.error?.message??'La demande ne peut pas être acceptée.');}finally{this.groupsBusy.set(false);}}
  async deleteGroup(group:SocialGroup){if(!confirm(`Supprimer le groupe « ${group.name} » ? Cette action retirera aussi ses demandes d’adhésion.`))return;this.groupsBusy.set(true);this.groupsError.set('');try{await firstValueFrom(this.http.delete(`${environment.apiUrl}/social/groups/${group.id}`));this.status.set(`Le groupe « ${group.name} » a été supprimé.`);await this.loadGroups();}catch(error:any){this.groupsError.set(error?.error?.message??'Le groupe n’a pas pu être supprimé.');}finally{this.groupsBusy.set(false);}}
  async toggleProfile(){this.profileOpen.update(open=>!open);this.accountOpen.set(false);this.notificationsOpen.set(false);this.blocksOpen.set(false);if(this.profileOpen()){try{const profile=await firstValueFrom(this.http.get<{displayName:string;bio:string;profileDiscoverable:boolean}>(environment.apiUrl+'/social/profile'));this.profileName.set(profile.displayName);this.profileBio=profile.bio;this.profileDiscoverable.set(profile.profileDiscoverable);}catch(error:any){this.error.set(error?.error?.message??'Le profil est inaccessible.');}}}
  async toggleAccount(){this.accountOpen.update(open=>!open);this.profileOpen.set(false);this.notificationsOpen.set(false);this.blocksOpen.set(false);if(this.accountOpen())await this.loadSessions();}
  async loadSessions(){try{this.sessions.set(await firstValueFrom(this.http.get<AccountSession[]>(environment.apiUrl+'/auth/social/account/sessions')));}catch(error:any){this.error.set(error?.error?.message??'Les sessions ne sont pas accessibles.');}}
  async revokeSession(session:AccountSession){if(!confirm(session.isCurrent?'Fermer cette session maintenant ?':'Révoquer cette session ?'))return;this.accountBusy.set(true);try{await firstValueFrom(this.http.delete(environment.apiUrl+`/auth/social/account/sessions/${session.id}`));this.status.set('La session a été révoquée.');await this.loadSessions();if(session.isCurrent)this.finish();}catch(error:any){this.error.set(error?.error?.message??'La session n’a pas pu être révoquée.');}finally{this.accountBusy.set(false);}}
  async changePassword(){this.accountBusy.set(true);try{await firstValueFrom(this.http.post(environment.apiUrl+'/auth/social/account/password',{currentPassword:this.currentPassword,newPassword:this.newPassword,confirmPassword:this.confirmPassword}));this.currentPassword='';this.newPassword='';this.confirmPassword='';this.status.set('Le mot de passe a été changé. Les autres sessions ont été révoquées.');await this.loadSessions();}catch(error:any){this.error.set(error?.error?.message??'Le mot de passe n’a pas pu être changé.');}finally{this.accountBusy.set(false);}}
  async exportData(){this.accountBusy.set(true);try{const data=await firstValueFrom(this.http.get(environment.apiUrl+'/auth/social/account/export',{responseType:'blob'}));const link=document.createElement('a'),url=URL.createObjectURL(data);link.href=url;link.download='mes-donnees-paroisse.json';link.click();URL.revokeObjectURL(url);this.status.set('Votre copie de données a été téléchargée.');}catch(error:any){this.error.set(error?.error?.message??'L’export n’a pas pu être créé.');}finally{this.accountBusy.set(false);}}
  async requestDeletion(){if(this.deletionReason.trim().length<8)return;this.accountBusy.set(true);try{const result=await firstValueFrom(this.http.delete<{scheduledAt:string}>(environment.apiUrl+'/auth/social/account',{body:{reason:this.deletionReason}}));this.status.set(`La fermeture du compte est programmée au ${this.formatDate(result.scheduledAt)}. Vous serez déconnecté.`);setTimeout(()=>this.finish(),1200);}catch(error:any){this.error.set(error?.error?.message??'La fermeture du compte n’a pas pu être programmée.');this.accountBusy.set(false);}}
  async setDiscoverability(value:boolean){try{const result=await firstValueFrom(this.http.patch<{profileDiscoverable:boolean}>(environment.apiUrl+'/social/settings',{profileDiscoverable:value}));this.profileDiscoverable.set(result.profileDiscoverable);this.status.set('Le réglage de confidentialité est enregistré.');}catch(error:any){this.error.set(error?.error?.message??'Le réglage de confidentialité n’a pas pu être enregistré.');}}
  async updateProfile(){this.profileSaving.set(true);try{const profile=await firstValueFrom(this.http.patch<{displayName:string;bio:string}>(environment.apiUrl+'/social/profile',{bio:this.profileBio}));this.profileName.set(profile.displayName);this.profileBio=profile.bio;this.status.set('Votre présentation a été mise à jour.');}catch(error:any){this.error.set(error?.error?.message??'La présentation n’a pas pu être enregistrée.');}finally{this.profileSaving.set(false);}}
  async toggleNotifications(){this.notificationsOpen.update(open=>!open);this.blocksOpen.set(false);if(this.notificationsOpen()){try{this.notices.set(await firstValueFrom(this.http.get<Array<{id:string;message:string;createdAt:string}>>(environment.apiUrl+'/auth/notifications')));}catch(error:any){this.error.set(error?.error?.message??'Les notifications ne sont pas accessibles.');}}}
  async toggleBlocks(){this.blocksOpen.update(open=>!open);this.notificationsOpen.set(false);if(this.blocksOpen()){try{this.blockedMembers.set(await firstValueFrom(this.http.get<BlockedMember[]>(environment.apiUrl+'/social/blocks')));}catch(error:any){this.error.set(error?.error?.message??'La liste des comptes bloqués est inaccessible.');}}}
  async unblock(member:BlockedMember){try{await firstValueFrom(this.http.delete(`${environment.apiUrl}/social/blocks/${member.id}`));this.blockedMembers.update(rows=>rows.filter(row=>row.id!==member.id));this.status.set(`${member.displayName} a été débloqué.`);void this.loadFeed();}catch(error:any){this.error.set(error?.error?.message??'Le compte n’a pas pu être débloqué.');}}
  toggleSaved(){this.savedMode.update(value=>!value);this.nextCursor.set(null);void this.loadFeed();}
  loadMore(){const cursor=this.nextCursor();if(cursor)void this.loadFeed(cursor);}
  togglePoll(){const enabled=!this.pollEnabled();this.pollEnabled.set(enabled);if(enabled){this.eventEnabled.set(false);this.resetEvent();this.visibility='TOUS_LES_FIDELES';this.clearMedia();}else{this.pollOptions=['',''];this.pollClosesAt='';}}
  toggleEvent(){const enabled=!this.eventEnabled();this.eventEnabled.set(enabled);if(enabled){this.pollEnabled.set(false);this.pollOptions=['',''];this.pollClosesAt='';this.visibility='TOUS_LES_FIDELES';this.clearMedia();}else this.resetEvent();}
  private resetEvent(){this.eventTitle='';this.eventStartsAt='';this.eventEndsAt='';this.eventLocation='';}
  eventInvalid(){if(this.eventTitle.trim().length<3||!this.eventStartsAt)return true;const start=new Date(this.eventStartsAt).getTime(),end=this.eventEndsAt?new Date(this.eventEndsAt).getTime():0;return !Number.isFinite(start)||start<Date.now()+5*60_000||start>Date.now()+365*86400_000||Boolean(this.eventEndsAt&&(!Number.isFinite(end)||end<=start||end>start+86400_000));}
  eventPast(event:SocialEvent){return new Date(event.startsAt)<=new Date();}
  formatEventDay(value:string){return new Intl.DateTimeFormat('fr-FR',{day:'2-digit'}).format(new Date(value));}
  formatEventMonth(value:string){return new Intl.DateTimeFormat('fr-FR',{month:'short'}).format(new Date(value)).replace('.','').toLocaleUpperCase('fr-FR');}
  async rsvpEvent(post:SocialPost,status:'PARTICIPATING'|'INTERESTED'|'DECLINED'){if(!post.event||this.eventPast(post.event))return;try{const event=await firstValueFrom(this.http.post<SocialEvent>(`${environment.apiUrl}/social/events/${post.event.id}/rsvp`,{status}));this.posts.update(posts=>posts.map(item=>item.id===post.id?{...item,event}:item));}catch(error:any){this.error.set(error?.error?.message??'Votre réponse n’a pas pu être enregistrée.');}}
  pollOptionsInvalid(){return this.pollOptions.some(option=>!option.trim());}
  addPollOption(){if(this.pollOptions.length<6)this.pollOptions=[...this.pollOptions,''];}
  removePollOption(index:number){if(this.pollOptions.length>2)this.pollOptions=this.pollOptions.filter((_,position)=>position!==index);}
  async votePoll(post:SocialPost,optionId:string){if(!post.poll||post.poll.closed)return;try{const poll=await firstValueFrom(this.http.post<SocialPoll>(`${environment.apiUrl}/social/polls/${post.poll.id}/vote`,{optionId}));this.posts.update(posts=>posts.map(item=>item.id===post.id?{...item,poll}:item));this.status.set('Votre vote a été enregistré.');}catch(error:any){this.error.set(error?.error?.message??'Votre vote n’a pas pu être enregistré.');}}
  edit(post:SocialPost){this.editingPostId.set(post.id);this.body=post.body;this.visibility=post.visibility;document.getElementById('post-body')?.scrollIntoView({behavior:'smooth',block:'center'});}
  cancelEdit(){this.editingPostId.set('');this.body='';this.visibility='TOUS_LES_FIDELES';}
  async publish(){const body=this.body.trim(),files=this.selectedMedia();if((!body&&!files.length)||this.busy())return;this.busy.set(true);this.error.set('');try{const editingId=this.editingPostId(),payload={body,visibility:this.visibility};if(editingId){const updated=await firstValueFrom(this.http.patch<SocialPost>(`${environment.apiUrl}/social/posts/${editingId}`,payload));this.posts.update(items=>items.map(item=>item.id===editingId?updated:item));this.status.set('Votre publication a été modifiée.');this.cancelEdit();}else if(this.eventEnabled()){const startsAt=new Date(this.eventStartsAt).toISOString(),endsAt=this.eventEndsAt?new Date(this.eventEndsAt).toISOString():undefined;await firstValueFrom(this.http.post(environment.apiUrl+'/social/events',{body,title:this.eventTitle.trim(),startsAt,...(endsAt?{endsAt}:{}),...(this.eventLocation.trim()?{location:this.eventLocation.trim()}: {})},{headers:new HttpHeaders({'Idempotency-Key':crypto.randomUUID()})}));await this.loadFeed();this.body='';this.eventEnabled.set(false);this.resetEvent();this.status.set('Votre événement a été publié.');}else if(this.pollEnabled()){const closesAt=this.pollClosesAt?new Date(this.pollClosesAt).toISOString():undefined;await firstValueFrom(this.http.post(environment.apiUrl+'/social/polls',{body,options:this.pollOptions.map(option=>option.trim()),...(closesAt?{closesAt}:{})},{headers:new HttpHeaders({'Idempotency-Key':crypto.randomUUID()})}));await this.loadFeed();this.body='';this.pollEnabled.set(false);this.pollOptions=['',''];this.pollClosesAt='';this.status.set('Votre sondage a été publié.');}else{let post:SocialPost;if(files.length){const form=new FormData();form.append('body',body);form.append('visibility',this.visibility);for(const file of files)form.append('media',file,file.name);post=await firstValueFrom(this.http.post<SocialPost>(environment.apiUrl+'/social/posts/media',form,{headers:new HttpHeaders({'Idempotency-Key':crypto.randomUUID()})}));}else post=await firstValueFrom(this.http.post<SocialPost>(environment.apiUrl+'/social/posts',payload,{headers:new HttpHeaders({'Idempotency-Key':crypto.randomUUID()})}));this.posts.update(items=>[post,...items]);for(const image of post.media??[])void this.loadMedia(image.id);this.body='';this.clearMedia();this.visibility='TOUS_LES_FIDELES';this.status.set('Votre publication a été ajoutée.');}}catch(error:any){this.error.set(error?.error?.message??'La publication n’a pas pu être enregistrée.');}finally{this.busy.set(false);}}
  async react(post:SocialPost,type:'AIME'|'COEUR'){const active=type==='AIME'?!post.likedByMe:!post.heartedByMe;try{await firstValueFrom(this.http.post(environment.apiUrl+'/social/reactions',{targetType:'post',targetId:post.id,type,active}));this.posts.update(rows=>rows.map(row=>row.id!==post.id?row:{...row,likedByMe:type==='AIME'?active:row.likedByMe,heartedByMe:type==='COEUR'?active:row.heartedByMe,likes:row.likes+(type==='AIME'?(active?1:-1):0),hearts:row.hearts+(type==='COEUR'?(active?1:-1):0)}));}catch(error:any){this.error.set(error?.error?.message??'La réaction n’a pas pu être enregistrée.');}}
  async toggleComments(post:SocialPost){if(this.openPost()===post.id){this.openPost.set('');return;}this.openPost.set(post.id);this.comments.set([]);try{this.comments.set(await firstValueFrom(this.http.get<SocialComment[]>(`${environment.apiUrl}/social/posts/${post.id}/comments`)));}catch(error:any){this.error.set(error?.error?.message??'Les commentaires ne sont pas accessibles.');}}
  replyTo(comment:SocialComment){this.replyParent=comment.id;this.commentBody='';document.getElementById(`comment-${this.openPost()}`)?.focus();}
  async sendComment(post:SocialPost){const body=this.commentBody.trim();if(!body||this.busy())return;this.busy.set(true);try{const parentId=this.replyParent||undefined,created=await firstValueFrom(this.http.post<Omit<SocialComment,'replies'>>(`${environment.apiUrl}/social/posts/${post.id}/comments`,{body,...(parentId?{parentId}:{})})),comment:SocialComment={...created,replies:[]};if(parentId)this.comments.update(rows=>rows.map(row=>row.id===parentId?{...row,replies:[...row.replies,comment]}:row));else this.comments.update(rows=>[...rows,comment]);this.posts.update(rows=>rows.map(row=>row.id===post.id?{...row,commentCount:row.commentCount+1}:row));this.commentBody='';this.replyParent='';}catch(error:any){this.error.set(error?.error?.message??'Le commentaire n’a pas pu être ajouté.');}finally{this.busy.set(false);}}
  async share(post:SocialPost){try{const shared=await firstValueFrom(this.http.post<SocialPost>(`${environment.apiUrl}/social/posts/${post.id}/share`,{}));this.posts.update(items=>[shared,...items.filter(item=>item.id!==shared.id)]);this.status.set('Publication repartagée dans votre espace.');}catch(error:any){this.error.set(error?.error?.message??'Le partage n’a pas pu être enregistré.');}}
  async save(post:SocialPost){const saved=!this.savedMode();try{await firstValueFrom(this.http.post(`${environment.apiUrl}/social/posts/${post.id}/save`,{saved}));if(!saved)this.posts.update(rows=>rows.filter(row=>row.id!==post.id));this.status.set(saved?'Publication enregistrée dans vos favoris.':'Publication retirée de vos favoris.');}catch(error:any){this.error.set(error?.error?.message??'La modification des favoris a échoué.');}}
  async deleteComment(comment:SocialComment){if(!confirm('Supprimer ce commentaire ?'))return;const isRoot=this.comments().some(row=>row.id===comment.id);try{await firstValueFrom(this.http.delete(`${environment.apiUrl}/social/comments/${comment.id}`));this.comments.update(rows=>rows.map(row=>row.id===comment.id?{...row,body:'Commentaire supprimé',canDelete:false}: {...row,replies:row.replies.map(reply=>reply.id===comment.id?{...reply,body:'Commentaire supprimé',canDelete:false}:reply)}));if(isRoot)this.posts.update(rows=>rows.map(row=>row.id===this.openPost()?{...row,commentCount:Math.max(0,row.commentCount-1)}:row));this.status.set('Commentaire supprimé.');}catch(error:any){this.error.set(error?.error?.message??'Le commentaire n’a pas pu être supprimé.');}}
  async block(post:SocialPost){if(!confirm(`Bloquer ${post.author.displayName} ? Ses publications ne s’afficheront plus dans votre fil.`))return;try{await firstValueFrom(this.http.post(`${environment.apiUrl}/social/blocks/${post.author.id}`,{}));this.posts.update(rows=>rows.filter(row=>row.author.id!==post.author.id));this.status.set('Ce compte est bloqué.');}catch(error:any){this.error.set(error?.error?.message??'Le compte n’a pas pu être bloqué.');}}
  async loadSettings(){try{const result=await firstValueFrom(this.http.get<{notificationsEnabled:boolean}>(environment.apiUrl+'/social/settings'));this.notificationsEnabled.set(result.notificationsEnabled);}catch{}}
  async setNotifications(enabled:boolean){try{await firstValueFrom(this.http.patch(environment.apiUrl+'/social/settings',{notificationsEnabled:enabled}));this.notificationsEnabled.set(enabled);}catch(error:any){this.error.set(error?.error?.message??'Le réglage des notifications n’a pas pu être enregistré.');}}
  async hide(post:SocialPost){try{await firstValueFrom(this.http.post(`${environment.apiUrl}/social/posts/${post.id}/hide`,{}));this.posts.update(rows=>rows.filter(row=>row.id!==post.id));this.status.set('Cette publication est masquée pour vous.');}catch(error:any){this.error.set(error?.error?.message??'La publication n’a pas pu être masquée.');}}
  async remove(post:SocialPost){if(!confirm('Supprimer cette publication ?'))return;try{await firstValueFrom(this.http.delete(`${environment.apiUrl}/social/posts/${post.id}`));this.posts.update(rows=>rows.filter(row=>row.id!==post.id));}catch(error:any){this.error.set(error?.error?.message??'La publication n’a pas pu être supprimée.');}}
  logout(){this.http.post(environment.apiUrl+'/auth/logout',{}).subscribe({complete:()=>this.finish(),error:()=>this.finish()});}
  private finish(){sessionStorage.clear();void this.router.navigate(['/connexion']);}
}
